let _index = null;
function buildIndex() {
  // [開始zip, cityIdx, 件数] を絶対値に復元して二分探索用の配列にする
  const out = [];
  let z = 0;
  for (const [d, c, n] of DB.d) { z += d; out.push([z, c, n]); }
  return out;
}

/** 7桁の郵便番号（ハイフン可）から住所を引く */
export function lookupZip(zip) {
  const s = String(zip || '').replace(/[^0-9]/g, '');
  if (s.length !== 7) return null;
  const n = parseInt(s, 10);
  if (!_index) _index = buildIndex();

  let lo = 0, hi = _index.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const [start, cityIdx, len] = _index[mid];
    if (n < start) hi = mid - 1;
    else if (n >= start + len) lo = mid + 1;
    else {
      const [pIdx, city] = DB.c[cityIdx];
      return { pref: DB.p[pIdx], city };
    }
  }
  return null;
}
